// The integer version of the Hurray C ABI exposed by this build.
//
// Callers SHOULD retrieve this at runtime via [`hurray_c_abi_version`] and
// compare it to the version they were compiled against.
//
// # Examples
//
// ```
// use hurray_ffi::HURRAY_C_ABI_VERSION;
//
// assert_eq!(HURRAY_C_ABI_VERSION, 10);
// ```
#define HURRAY_C_ABI_VERSION 10

// UTF-8 string: `data` and `data_len`. Not NUL-terminated.
#define HURRAY_KV_STRING 1

// Signed 64-bit integer: `i64_value`.
#define HURRAY_KV_INT64 2

// Unsigned 64-bit integer: `u64_value`.
#define HURRAY_KV_UINT64 3

// IEEE 754 binary64: `f64_value`.
#define HURRAY_KV_FLOAT64 4

// Boolean: `bool_value`.
#define HURRAY_KV_BOOL 5

// Opaque bytes: `data` and `data_len`.
#define HURRAY_KV_BYTES 6

// Homogeneous array of scalars: `items` and `item_count`.
#define HURRAY_KV_ARRAY 7

// A plain tensor: it owns buffers and no node after it belongs to it.
//
// Unlike the `HURRAY_KV_*` tags, these two are **not** wire values: the wire has no
// tensor-or-composite tag, it has a composite *layout* (tag `0x0B`). The kind is here so
// that walking the array needs no descriptor decode, and so that a head with
// `member_count == 0` — which the layout permits — is still distinguishable from a
// tensor.
#define HURRAY_ITEM_TENSOR 0

// A composite head: it owns no buffers, and the next `member_count` sibling-level nodes
// are its members.
#define HURRAY_ITEM_COMPOSITE 1

// Opaque handle to a buffer registered with the Hurray C ABI.
//
// This struct is **not** `#[repr(C)]`; its internal layout is an
// implementation detail. Callers MUST treat it as a black-box opaque
// pointer. The handle is heap-allocated by [`hurray_buffer_from_ptr`] and
// MUST be released exactly once by [`hurray_buffer_destroy`].
typedef struct HurrayBuffer HurrayBuffer;

// Opaque handle to an ordered, owning list of [`HurrayBuffer`] handles.
//
// Like [`HurrayBuffer`], this struct is **not** `#[repr(C)]`; its layout is an
// implementation detail and callers MUST treat it as a black-box pointer.
// Keeping it opaque is what allows [`hurray_buffer_list_get`] to bounds-check
// and to hand back a borrowed handle — a bare `HurrayBuffer**` array could do
// neither.
typedef struct HurrayBufferList HurrayBufferList;

// Opaque handle to a decoded tensor descriptor.
//
// This struct is **not** `#[repr(C)]`; its layout is an implementation
// detail. Callers MUST treat it as a black-box opaque pointer created by
// [`hurray_descriptor_decode`] and destroyed by [`hurray_descriptor_destroy`].
typedef struct HurrayDescriptor HurrayDescriptor;

// Opaque handle to a blocking file reader.
//
// Not `#[repr(C)]`; the layout is an implementation detail. Created by
// [`hurray_file_reader_new`] and released exactly once by [`hurray_file_reader_destroy`].
//
// One handle, one thread at a time.
typedef struct HurrayFileReader HurrayFileReader;

// Opaque handle to a blocking file writer.
//
// Not `#[repr(C)]`; the layout is an implementation detail. Created by
// [`hurray_file_writer_new`] and released exactly once by
// [`hurray_file_writer_destroy`].
//
// One handle, one thread at a time.
typedef struct HurrayFileWriter HurrayFileWriter;

// Opaque handle to one read item: a tensor, or a composite and its whole subtree.
//
// Not `#[repr(C)]`; the layout is an implementation detail. The handle **owns** every
// node's tensor and name, and one [`hurray_item_destroy`] releases all of them.
//
// A plain tensor is an item of exactly one node, so a caller that does not care about
// composites can read `hurray_item_node(item, 0, &node)` and ignore the rest.
typedef struct HurrayItem HurrayItem;

// Opaque handle to a blocking stream reader.
//
// Not `#[repr(C)]`; the layout is an implementation detail. Created by
// [`hurray_reader_new`] and released exactly once by [`hurray_reader_destroy`].
//
// One handle, one thread at a time.
typedef struct HurrayReader HurrayReader;

// Opaque handle to a tensor: its descriptor and its buffers.
//
// Not `#[repr(C)]`; the layout is an implementation detail. The handle **owns** both
// halves. [`hurray_tensor_descriptor`] and [`hurray_tensor_buffers`] hand out *borrowed*
// pointers — valid until [`hurray_tensor_destroy`], and never to be destroyed
// individually.
typedef struct HurrayTensor HurrayTensor;

// Opaque handle to a blocking stream writer.
//
// Not `#[repr(C)]`; the layout is an implementation detail. Created by
// [`hurray_writer_new`] and released exactly once by [`hurray_writer_destroy`].
//
// One handle, one thread at a time.
typedef struct HurrayWriter HurrayWriter;

// Integer status code returned by every Hurray C ABI function.
//
// Zero (`HURRAY_OK`) indicates success. All negative values indicate errors.
// Positive values report a normal, non-error outcome that is not plain success;
// [`HURRAY_END_OF_STREAM`] is the only one so far.
//
// # Examples
//
// ```
// use hurray_ffi::{HurrayStatus, HURRAY_OK};
//
// fn check(s: HurrayStatus) {
//     assert_eq!(s, HURRAY_OK);
// }
// check(HURRAY_OK);
// ```
typedef int32_t HurrayStatus;

// Optional release callback invoked by [`hurray_buffer_destroy`].
//
// The first argument is the `data` pointer passed to [`hurray_buffer_from_ptr`].
// The second argument is the `release_context` pointer passed to the same
// function. Both arguments carry the exact values provided at construction time.
//
// Implementations MUST NOT call back into the Hurray C ABI from within this
// callback; doing so may cause deadlocks or use-after-free.
typedef void (*HurrayReleaseCallback)(void*, void*);

// Payload for the `ConsumerStream` sync mode handoff.
//
// The consumer supplies this struct when calling
// [`hurray_buffer_handoff_consumer_stream`] to declare the stream on which
// they intend to use the buffer.
