// `buffer` and `out_alignment` MUST be valid, non-null pointers.
 HurrayStatus hurray_buffer_alignment(const struct HurrayBuffer *buffer, uint32_t *out_alignment) ;

// Reads the byte size of a buffer handle.
//
// # Safety
//
// `buffer` and `out_byte_size` MUST be valid, non-null pointers.
 HurrayStatus hurray_buffer_byte_size(const struct HurrayBuffer *buffer, uint64_t *out_byte_size) ;

// Reads the raw data pointer stored in a buffer handle.
//
// # Safety
//
// `buffer` and `out_data` MUST be valid, non-null pointers.
 HurrayStatus hurray_buffer_data_ptr(const struct HurrayBuffer *buffer, void **out_data) ;

// Destroys a [`HurrayBuffer`] handle and invokes the release callback.
//
// After this call, `buffer` is no longer valid and MUST NOT be dereferenced.
// In debug builds, a double-free attempt returns [`HURRAY_ERR_INTERNAL`].
//
// # Safety
//
// - `buffer` MUST have been created by [`hurray_buffer_from_ptr`].
// - `buffer` MUST NOT have been previously destroyed.
 HurrayStatus hurray_buffer_destroy(struct HurrayBuffer *buffer) ;

// Reads the device tag wire byte of a buffer handle.
//
// # Safety
//
// `buffer` and `out_device_tag` MUST be valid, non-null pointers.
 HurrayStatus hurray_buffer_device_tag(const struct HurrayBuffer *buffer, uint8_t *out_device_tag) ;

// Creates a new [`HurrayBuffer`] handle from a raw data pointer and metadata.
//
// The caller retains ownership of `data` until the handle is destroyed via
// [`hurray_buffer_destroy`], at which point the `release` callback (if
// non-null) is invoked with `(data, release_context)`. If `release` is null,
// the caller is responsible for freeing `data` after destroying the handle.
//
// # Arguments
//
// - `data` — Non-null pointer to the first byte of the buffer. MUST be
//   aligned to at least `alignment` bytes.
// - `byte_size` — Length of the buffer in bytes.
// - `alignment` — Declared alignment of `data` in bytes; MUST be a power of
//   two and at least [`hurray_core::MIN_BUFFER_ALIGNMENT`] for non-empty
//   buffers.
// - `device_tag` — Wire byte identifying the memory space (see
//   `docs/spec/buffer-protocol.md § Device Tags`).
// - `sync_mode` — Wire byte for producer/consumer ordering (see
//   `docs/spec/buffer-protocol.md § Synchronization Mode`).
// - `memory_class` — Wire byte for memory accessibility class.
// - `release` — Optional callback invoked on [`hurray_buffer_destroy`].
// - `release_context` — Opaque context pointer forwarded to `release`; MAY
//   be null.
// - `out_handle` — Non-null pointer to a `*mut HurrayBuffer`; set to the
//   newly allocated handle on success.
//
// # Safety
//
// - `data` MUST be a valid, non-null pointer to at least `byte_size` bytes.
// - `data` MUST remain valid until the release callback is called.
// - `out_handle` MUST be a valid, non-null, writable pointer.
// - `release_context` lifetime is caller-managed; it MUST remain valid until
//   the release callback returns.

HurrayStatus hurray_buffer_from_ptr(void *data,
                                    uint64_t byte_size,
                                    uint32_t alignment,
                                    uint8_t device_tag,
                                    uint8_t sync_mode,
                                    uint8_t memory_class,
                                    HurrayReleaseCallback release,
                                    void *release_context,
                                    struct HurrayBuffer **out_handle)
;

// Validates a `ConsumerStream`-mode sync handoff from producer to consumer.
//
// Checks that:
// - The buffer's declared sync mode is [`SyncMode::ConsumerStream`].
// - `payload.consumer_stream` is non-null.
// - `payload.consumer_stream_device_tag` matches the buffer's declared device
//   tag.
//
// Returns [`HURRAY_OK`] if all checks pass; [`HURRAY_ERR_SYNC_MODE_MISMATCH`]
// otherwise.
//
// # Safety
//
// `buffer` and `payload` MUST be valid, non-null pointers pointing to live
// objects.

HurrayStatus hurray_buffer_handoff_consumer_stream(const struct HurrayBuffer *buffer,
                                                   const struct HurraySyncConsumerStreamPayload *payload)
;

// Validates an `Event`-mode sync handoff from producer to consumer.
//
// Checks that:
// - The buffer's declared sync mode is [`SyncMode::Event`].
// - `payload.sync_handle` is non-null.
// - `payload.event_release_fn` is non-null.
// - `payload.sync_handle_device_tag` matches the buffer's declared device tag.
//
// Returns [`HURRAY_OK`] if all checks pass; [`HURRAY_ERR_SYNC_MODE_MISMATCH`]
// otherwise.
//
// # Safety
//
// `buffer` and `payload` MUST be valid, non-null pointers pointing to live
// objects.

HurrayStatus hurray_buffer_handoff_event(const struct HurrayBuffer *buffer,
                                         const struct HurraySyncEventPayload *payload)
;

// Validates a `ProducerSynced`-mode sync handoff.
//
// Checks that the buffer's declared sync mode is
// [`SyncMode::ProducerSynced`]. This mode requires no payload — calling
// this function is itself the assertion that the producer has already issued
// a host-side wait.
//
// Returns [`HURRAY_OK`] if the buffer is `ProducerSynced`;
// [`HURRAY_ERR_SYNC_MODE_MISMATCH`] otherwise.
//
// # Safety
//
// `buffer` MUST be a valid, non-null pointer to a live [`HurrayBuffer`].
 HurrayStatus hurray_buffer_handoff_producer_synced(const struct HurrayBuffer *buffer) ;

// Destroys `*list` and every [`HurrayBuffer`] it owns, then writes null through
// `list`.
//
// Nulling the caller's pointer is the sound half of Arrow's "release marks the
// structure released" discipline: the list allocation itself is freed here, so
// a marker written inside it could not be read back, but the caller's own
// variable can be invalidated.
//
// Each owned slot is nulled as its handle is destroyed, so a release callback
// that panics or re-enters cannot cause a double free. A panicking callback
// leaks the remainder of the list rather than corrupting it.
//
// Passing a pointer to a null pointer is a no-op and returns [`HURRAY_OK`],
// which makes cleanup paths idempotent.
//
// # Safety
//
// - `list` MUST be a valid, non-null, writable pointer to a `*mut HurrayBufferList`.
// - `*list` MUST be a live handle from [`hurray_buffer_list_new`], or null.
//
// # Examples
//
// ```
// use hurray_ffi::buffer_list::{hurray_buffer_list_destroy, hurray_buffer_list_new};
// use hurray_ffi::{HurrayBufferList, HURRAY_OK};
//
// let mut list: *mut HurrayBufferList = std::ptr::null_mut();
// unsafe { hurray_buffer_list_new(0, &mut list) };
//
// assert_eq!(unsafe { hurray_buffer_list_destroy(&mut list) }, HURRAY_OK);
// assert!(list.is_null());
//
// // Idempotent: destroying an already-nulled pointer is a no-op.
// assert_eq!(unsafe { hurray_buffer_list_destroy(&mut list) }, HURRAY_OK);
// ```
 HurrayStatus hurray_buffer_list_destroy(struct HurrayBufferList **list) ;

// Borrows the [`HurrayBuffer`] at `index`.
//
// The returned handle is **borrowed**: ownership stays with the list, and the
// caller MUST NOT call `hurray_buffer_destroy` on it. It stays valid until the
// list is destroyed.
//
// Returns [`HURRAY_ERR_INDEX_OUT_OF_BOUNDS`] if `index` is not less than the
// list length.
//
// # Safety
//
// - `list` MUST be a live handle from [`hurray_buffer_list_new`].
// - `out_buffer` MUST be a valid, non-null, writable pointer.
//
// # Examples
//
// ```
// use hurray_ffi::buffer_list::{
//     hurray_buffer_list_destroy, hurray_buffer_list_get, hurray_buffer_list_new,
// };
// use hurray_ffi::status::HURRAY_ERR_INDEX_OUT_OF_BOUNDS;
// use hurray_ffi::{HurrayBuffer, HurrayBufferList};
//
// let mut list: *mut HurrayBufferList = std::ptr::null_mut();
// unsafe { hurray_buffer_list_new(0, &mut list) };
//
// // An empty list has no index 0.
// let mut got: *mut HurrayBuffer = std::ptr::null_mut();
// assert_eq!(
//     unsafe { hurray_buffer_list_get(list, 0, &mut got) },
//     HURRAY_ERR_INDEX_OUT_OF_BOUNDS
// );
//
// unsafe { hurray_buffer_list_destroy(&mut list) };
// ```

HurrayStatus hurray_buffer_list_get(const struct HurrayBufferList *list,
                                    uint64_t index,
                                    struct HurrayBuffer **out_buffer)
;

// Reads the number of buffers in `list`.
//
// # Safety
//
// - `list` MUST be a live handle from [`hurray_buffer_list_new`].
// - `out_len` MUST be a valid, non-null, writable pointer.
//
// # Examples
//
// ```
// use hurray_ffi::buffer_list::{
//     hurray_buffer_list_destroy, hurray_buffer_list_len, hurray_buffer_list_new,
// };
// use hurray_ffi::{HurrayBufferList, HURRAY_OK};
//
// let mut list: *mut HurrayBufferList = std::ptr::null_mut();
// unsafe { hurray_buffer_list_new(0, &mut list) };
//
// let mut len: u64 = 7;
// assert_eq!(unsafe { hurray_buffer_list_len(list, &mut len) }, HURRAY_OK);
// assert_eq!(len, 0);
//
// unsafe { hurray_buffer_list_destroy(&mut list) };
// ```
 HurrayStatus hurray_buffer_list_len(const struct HurrayBufferList *list, uint64_t *out_len) ;

// Creates an empty [`HurrayBufferList`].
//
// `capacity` is a hint only; the list grows as needed. Pass the tensor's
// buffer count to avoid reallocation.
//
// The caller owns the returned list and MUST destroy it exactly once with
// [`hurray_buffer_list_destroy`].
//
// # Safety
//
// `out_list` MUST be a valid, non-null, writable pointer.
//
// # Examples
//
// ```
// use hurray_ffi::buffer_list::{hurray_buffer_list_destroy, hurray_buffer_list_new};
// use hurray_ffi::{HurrayBufferList, HURRAY_OK};
//
// let mut list: *mut HurrayBufferList = std::ptr::null_mut();
// assert_eq!(unsafe { hurray_buffer_list_new(2, &mut list) }, HURRAY_OK);
// assert!(!list.is_null());
//
// assert_eq!(unsafe { hurray_buffer_list_destroy(&mut list) }, HURRAY_OK);
// assert!(list.is_null()); // destroy nulls the caller's pointer
// ```
 HurrayStatus hurray_buffer_list_new(uint64_t capacity, struct HurrayBufferList **out_list) ;

// Appends `buffer` to `list`, transferring ownership of the handle to the list.
//
// On success the caller MUST NOT destroy `buffer` — destroying the list
// destroys it. On failure ownership stays with the caller.
//
// Buffers MUST be pushed in descriptor buffer-table order: the first push is
// buffer index `0`, the second is index `1`, and so on.
//
// # Safety
//
// - `list` MUST be a live handle from [`hurray_buffer_list_new`].
// - `buffer` MUST be a live handle from `hurray_buffer_from_ptr` that has not
//   been destroyed and is not already owned by another list.
//
// # Examples
//
// ```
// use hurray_ffi::buffer::hurray_buffer_from_ptr;
// use hurray_ffi::buffer_list::{
//     hurray_buffer_list_destroy, hurray_buffer_list_len, hurray_buffer_list_new,
//     hurray_buffer_list_push,
// };
// use hurray_ffi::{HurrayBuffer, HurrayBufferList, HURRAY_OK};
//
// #[repr(align(64))]
// struct Aligned([u8; 64]);
// let mut data = Aligned([0u8; 64]);
//
// let mut buffer: *mut HurrayBuffer = std::ptr::null_mut();
// assert_eq!(
//     unsafe {
//         hurray_buffer_from_ptr(
//             data.0.as_mut_ptr().cast(), 64, 64, 0, 0, 0,
//             None, std::ptr::null_mut(), &mut buffer,
//         )
//     },
//     HURRAY_OK
// );
//
// let mut list: *mut HurrayBufferList = std::ptr::null_mut();
// unsafe { hurray_buffer_list_new(1, &mut list) };
// assert_eq!(unsafe { hurray_buffer_list_push(list, buffer) }, HURRAY_OK);
//
// let mut len: u64 = 0;
// unsafe { hurray_buffer_list_len(list, &mut len) };
// assert_eq!(len, 1);
//
// // Destroying the list destroys the pushed buffer too.
// unsafe { hurray_buffer_list_destroy(&mut list) };
// ```
 HurrayStatus hurray_buffer_list_push(struct HurrayBufferList *list, struct HurrayBuffer *buffer) ;

