// Reads a real scalar field of the descriptor.
//
// Covers per-tensor affine `scale` — a `float32` on the wire, widened — and the
// six `float64` statistics. A statistic whose `computed_mask` guard bit is
// clear returns [`HURRAY_ERR_FIELD_NOT_PRESENT`](crate::status::HURRAY_ERR_FIELD_NOT_PRESENT) rather than the stored
// placeholder, so a caller cannot read an uncomputed value by forgetting to
// test the mask.
//
// # Errors
//
// As [`hurray_descriptor_field_u64`], with
// [`HURRAY_ERR_FIELD_NOT_APPLICABLE`] for any field that is not a real scalar.
//
// # Safety
//
// `handle` and `out_value` MUST be valid, non-null pointers, and `handle` MUST
// NOT have been destroyed.

HurrayStatus hurray_descriptor_field_f64(const struct HurrayDescriptor *handle,
                                         HurrayDescriptorField field,
                                         uint32_t level,
                                         double *out_value)
;

// Reads a signed scalar field of the descriptor.
//
// Only per-tensor affine `zero_point` is signed; it is an `int32` on the wire
// and widens losslessly. Separate from [`hurray_descriptor_field_u64`] because
// an unsigned accessor would report a negative zero point as a huge positive
// number, which is exactly the kind of silent corruption a quantized read
// cannot absorb.
//
// # Errors
//
// As [`hurray_descriptor_field_u64`], with
// [`HURRAY_ERR_FIELD_NOT_APPLICABLE`] for any field that is not a signed
// scalar.
//
// # Safety
//
// `handle` and `out_value` MUST be valid, non-null pointers, and `handle` MUST
// NOT have been destroyed.

HurrayStatus hurray_descriptor_field_i64(const struct HurrayDescriptor *handle,
                                         HurrayDescriptorField field,
                                         uint32_t level,
                                         int64_t *out_value)
;

// Reads a signed array field of the descriptor.
//
// Signed because strides may be negative (reversed) or zero (broadcast), which
// an unsigned accessor would misreport. The capacity/length protocol is the one
// [`hurray_descriptor_field_u64_array`] documents.
//
// # Errors
//
// As [`hurray_descriptor_field_u64_array`].
//
// # Safety
//
// - `handle` and `out_len` MUST be valid, non-null pointers.
// - If `out_values` is non-null it MUST be writable for `capacity` × 8 bytes,
//   where `capacity` is the value at `*out_len` on entry.

HurrayStatus hurray_descriptor_field_i64_array(const struct HurrayDescriptor *handle,
                                               HurrayDescriptorField field,
                                               uint32_t level,
                                               int64_t *out_values,
                                               uintptr_t *out_len)
;

// Reads an unsigned or boolean scalar field of the descriptor.
//
// Covers every scalar field that is unsigned or boolean, which is all of them
// but two: a boolean reads as `0` or `1`, and a wire tag byte — `kv_role`,
// `block_table_index_type`, `scale_type`, `member_role`, the quantization
// scheme tag — reads as its documented value. The two exceptions are
// [`hurray_descriptor_field_i64`] and [`hurray_descriptor_field_f64`].
//
// # Arguments
//
// - `handle` — Descriptor created by
//   [`hurray_descriptor_decode`](crate::hurray_descriptor_decode).
// - `field` — One of the `HURRAY_*_FIELD_*` unsigned scalar constants.
// - `level` — Tiled nesting level to read; MUST be `0` for every other layout
//   and for every section field.
// - `out_value` — Non-null pointer; written only on [`HURRAY_OK`].
//
// # Errors
//
// - [`HURRAY_ERR_FIELD_NOT_APPLICABLE`] — `field` does not belong to this
//   descriptor's layout or quantization scheme, or is not an unsigned scalar.
// - [`HURRAY_ERR_FIELD_NOT_PRESENT`](crate::status::HURRAY_ERR_FIELD_NOT_PRESENT) — the field is optional and this
//   descriptor does not carry it: an absent section, an unset optional field,
//   or a statistic whose `computed_mask` guard bit is clear.
// - [`HURRAY_ERR_INDEX_OUT_OF_BOUNDS`](crate::status::HURRAY_ERR_INDEX_OUT_OF_BOUNDS) — `level` exceeds the nesting depth, or
//   is non-zero for a field that does not nest.
//
// # Safety
//
// `handle` and `out_value` MUST be valid, non-null pointers, and `handle` MUST
// NOT have been destroyed.

HurrayStatus hurray_descriptor_field_u64(const struct HurrayDescriptor *handle,
                                         HurrayDescriptorField field,
                                         uint32_t level,
                                         uint64_t *out_value)
;

// Reads an unsigned array field of the descriptor.
//
// Uses the capacity/length in-out pattern
// [`hurray_descriptor_shape`](crate::descriptor::hurray_descriptor_shape) uses:
//
// 1. Set `*out_len` to the capacity of `out_values` in elements, or `0` if
//    `out_values` is null.
// 2. On return `*out_len` always holds the field's true length.
// 3. A null `out_values` or an insufficient capacity returns
//    [`HURRAY_ERR_BUFFER_TOO_SMALL`], so the caller can allocate and retry.
//
// # Errors
//
// As [`hurray_descriptor_field_u64`], plus [`HURRAY_ERR_BUFFER_TOO_SMALL`] per
// the protocol above.
//
// # Safety
//
// - `handle` and `out_len` MUST be valid, non-null pointers.
// - If `out_values` is non-null it MUST be writable for `capacity` × 8 bytes,
//   where `capacity` is the value at `*out_len` on entry.

HurrayStatus hurray_descriptor_field_u64_array(const struct HurrayDescriptor *handle,
                                               HurrayDescriptorField field,
                                               uint32_t level,
                                               uint64_t *out_values,
                                               uintptr_t *out_len)
;

// Reads the layout tag byte of the tensor descriptor.
//
// # Safety
//
// `handle` and `out_tag` MUST be valid, non-null pointers.

HurrayStatus hurray_descriptor_layout_tag(const struct HurrayDescriptor *handle,
                                          uint8_t *out_tag)
;

// Reads the rank (number of dimensions) of the tensor descriptor.
//
// # Safety
//
// `handle` and `out_rank` MUST be valid, non-null pointers.
 HurrayStatus hurray_descriptor_rank(const struct HurrayDescriptor *handle, uint32_t *out_rank) ;

// Reads the shape (dimension sizes) of a tensor descriptor.
//
// This function uses a **capacity/length in-out pattern**:
//
// 1. Set `*out_rank` to the capacity of the `out_dims` array (number of
//    `uint64_t` elements it can hold), or to `0` if `out_dims` is null.
// 2. On return, `*out_rank` always contains the true rank of the tensor.
// 3. If `out_dims` is null OR the capacity was less than the true rank,
//    the function returns [`HURRAY_ERR_BUFFER_TOO_SMALL`] and `*out_rank`
//    contains the true rank so the caller can allocate and retry.
// 4. Otherwise the function writes the dimension sizes into `out_dims[0..rank]`
//    and returns [`HURRAY_OK`].
//
// # Safety
//
// - `handle` and `out_rank` MUST be valid, non-null pointers.
// - If `out_dims` is non-null it MUST be writable for `capacity` × 8 bytes,
//   where `capacity` is the value at `*out_rank` on entry.

HurrayStatus hurray_descriptor_shape(const struct HurrayDescriptor *handle,
                                     uint64_t *out_dims,
                                     uintptr_t *out_rank)
;

// Destroys a reader, releases its transport context, and writes null through `handle`.
//
// Tensors already produced by [`hurray_file_reader_read_tensor`] are unaffected: each
// owns its own buffers and outlives the reader. Name and KV pointers are *not* — they
// borrow from the handle and die with it.
//
// # Safety
//
// - `handle` MUST be a valid, non-null pointer to a `*mut HurrayFileReader` from
//   [`hurray_file_reader_new`].
// - That reader MUST NOT have been destroyed already.
 HurrayStatus hurray_file_reader_destroy(struct HurrayFileReader **handle) ;

// Writes the number of entries in the file's KV metadata section.
//
// # Safety
//
// `handle` and `out_count` MUST be valid, non-null pointers.

HurrayStatus hurray_file_reader_kv_count(const struct HurrayFileReader *handle,
                                         uint64_t *out_count)
;

// Copies KV entry `index` — its key and its typed value — into `out_entry`.
//
// The pointers inside the entry borrow from the reader: valid until
// [`hurray_file_reader_destroy`], never to be freed. The entry can be handed straight to
// [`hurray_file_writer_finish`][crate::file::hurray_file_writer_finish], which is how a
// KV section is copied from one file into another without being transcribed.
//
// Returns [`HURRAY_ERR_INDEX_OUT_OF_BOUNDS`][crate::HURRAY_ERR_INDEX_OUT_OF_BOUNDS] if
// `index` is past the end.
//
// # Safety
//
// `handle` MUST point to a live [`HurrayFileReader`], and `out_entry` MUST be a valid,
// non-null pointer writable for one [`HurrayKvEntry`].

HurrayStatus hurray_file_reader_kv_entry(const struct HurrayFileReader *handle,
                                         uint64_t index,
                                         struct HurrayKvEntry *out_entry)
;

// Opens a Hurray file over `transport`: header, trailer, footer index and KV section.
//
// The transport's `read_at` and `size` callbacks are both required — the container is
// located from its end, so its size is a precondition of opening it. The vtable is
// copied, so the caller MAY free the [`HurrayTransport`] struct immediately; its `ctx`
// must stay valid until the reader is destroyed, at which point the vtable's release
// callback is invoked.
//
// Returns:
//
// - [`HURRAY_OK`] — `*out_handle` is a new reader.
// - [`HURRAY_ERR_INVALID_MAGIC`][crate::HURRAY_ERR_INVALID_MAGIC] — not a `HRRYFILE`.
// - [`HURRAY_ERR_VERSION_MISMATCH`][crate::HURRAY_ERR_VERSION_MISMATCH] — a container
//   version this build does not read.
// - [`HURRAY_ERR_INVALID_FILE`][crate::HURRAY_ERR_INVALID_FILE] — the footer does not
//   check out: a CRC mismatch, an index overrunning the trailer, unknown header flags.
// - [`HURRAY_ERR_UNEXPECTED_EOF`][crate::HURRAY_ERR_UNEXPECTED_EOF] — the file is
//   shorter than its own structure claims.
// - Whatever status a callback returned, if it failed. A failed open is terminal: there
//   is no index to start from, so create a new reader rather than retrying this one.
//
// # Safety
//
// - `transport` MUST point to a readable [`HurrayTransport`] for the duration of the call.
// - `out_handle` MUST be a valid, non-null, writable pointer.

HurrayStatus hurray_file_reader_new(const struct HurrayTransport *transport,
                                    struct HurrayFileReader **out_handle)
;

// Reads the composite headed by `name`: its head, its members, and their members.
//
// Membership is recovered from the head's declared `member_count` and the file order of
// the index entries that follow it, then validated — member count, partition exact-cover,
// overlay base-first ordering, at every level of nesting.
//
// `*out_item` is **owned** by the caller and released with
// [`hurray_item_destroy`][crate::hurray_item_destroy], which frees every tensor in the
// subtree. Its nodes are in preorder, with each node declaring how many of the nodes
// after it are its members — see [`crate::item`] for the walk. Every member carries its
// own name, because every tensor in a file has its own index entry.
//
// Returns:
//
// - [`HURRAY_OK`] — `*out_item` is a new [`HurrayItem`].
// - [`HURRAY_ERR_NOT_FOUND`][crate::HURRAY_ERR_NOT_FOUND] — no such name in the index.
// - [`HURRAY_ERR_NOT_COMPOSITE`][crate::HURRAY_ERR_NOT_COMPOSITE] — the name is in the
//   index but its descriptor is not a composite head. Refused at descriptor time, before
//   a byte of any data region is read.
// - [`HURRAY_ERR_INVALID_FILE`][crate::HURRAY_ERR_INVALID_FILE] — the group is torn: the
//   head declares more members than follow it, or a level fails validation.
// - [`HURRAY_ERR_LIMIT_EXCEEDED`][crate::HURRAY_ERR_LIMIT_EXCEEDED] — nesting exceeded
//   the core's maximum composite depth.
// - Whatever status the `read_at` callback returned, if it failed. Every request was an
//   absolute range, so the reader stays usable and the call MAY be retried.
//
// # Safety
//
// - `handle` MUST point to a live [`HurrayFileReader`].
// - `name` MUST be readable for `name_len` bytes.
// - `out_item` MUST be a valid, non-null, writable pointer.

HurrayStatus hurray_file_reader_read_composite(struct HurrayFileReader *handle,
                                               const uint8_t *name,
                                               uintptr_t name_len,
                                               struct HurrayItem **out_item)
;

// Reads the descriptor of the tensor named `name`, without reading a byte of its data.
//
// What a loader inspects before deciding whether it wants the tensor at all: element
// type, shape, layout, quantization.
//
// `*out_descriptor` is **owned** by the caller and released with
// [`hurray_descriptor_destroy`][crate::descriptor::hurray_descriptor_destroy].
//
// Returns [`HURRAY_ERR_NOT_FOUND`][crate::HURRAY_ERR_NOT_FOUND] if the name is not in
// the index. A failed read leaves the reader usable: the request was for an absolute
// range, so nothing about the reader's position is lost.
//
// # Safety
//
// - `handle` MUST point to a live [`HurrayFileReader`].
// - `name` MUST be readable for `name_len` bytes.
// - `out_descriptor` MUST be a valid, non-null, writable pointer.

HurrayStatus hurray_file_reader_read_descriptor(struct HurrayFileReader *handle,
                                                const uint8_t *name,
                                                uintptr_t name_len,
                                                struct HurrayDescriptor **out_descriptor)
;

// Reads the tensor named `name`: its descriptor and every data buffer.
//
// `*out_tensor` is **owned** by the caller and released with
// [`hurray_tensor_destroy`][crate::hurray_tensor_destroy], which frees both halves.
//
// Every buffer points at memory the core allocated at the alignment its buffer handle
// *declares*, which the transport wrote into directly — so a SIMD load on it is sound,
// and no copy of the payload happened after that write.
//
// Returns [`HURRAY_ERR_NOT_FOUND`][crate::HURRAY_ERR_NOT_FOUND] for a name that is not
// in the index. A composite head reads back as the buffer-less tensor it is in the file;
// [`hurray_file_reader_read_composite`] reads it with its members instead.
//
// # Safety
//
// - `handle` MUST point to a live [`HurrayFileReader`].
// - `name` MUST be readable for `name_len` bytes.
// - `out_tensor` MUST be a valid, non-null, writable pointer.

HurrayStatus hurray_file_reader_read_tensor(struct HurrayFileReader *handle,
                                            const uint8_t *name,
                                            uintptr_t name_len,
                                            struct HurrayTensor **out_tensor)
;

// Writes the number of tensors in the file's footer index.
//
// Every tensor is individually addressable, composite heads and members included.
//
// # Safety
//
// `handle` and `out_count` MUST be valid, non-null pointers.

HurrayStatus hurray_file_reader_tensor_count(const struct HurrayFileReader *handle,
                                             uint64_t *out_count)
;

// Borrows the name of index entry `index` as UTF-8 bytes.
//
// The bytes are **not** NUL-terminated and are owned by the reader: valid until
// [`hurray_file_reader_destroy`], never to be freed by the caller.
//
// Returns [`HURRAY_ERR_INDEX_OUT_OF_BOUNDS`][crate::HURRAY_ERR_INDEX_OUT_OF_BOUNDS] if
// `index` is past the end.
//
// # Safety
//
// `handle`, `out_name` and `out_len` MUST be valid, non-null pointers.

HurrayStatus hurray_file_reader_tensor_name(const struct HurrayFileReader *handle,
                                            uint64_t index,
                                            const uint8_t **out_name,
                                            uintptr_t *out_len)
;

// Destroys a writer, releases its transport context, and writes null through `handle`.
//
// Destroying a writer that was never finished leaves a file with no footer, which no
// reader can open — the bytes are not a container until
// [`hurray_file_writer_finish`] has written its index and trailer.
//
// # Safety
//
// - `handle` MUST be a valid, non-null pointer to a `*mut HurrayFileWriter` from
//   [`hurray_file_writer_new`].
// - That writer MUST NOT have been destroyed already.
 HurrayStatus hurray_file_writer_destroy(struct HurrayFileWriter **handle) ;

// Writes the KV section, the footer index and the 40-byte trailer, completing the file.
//
// Until this returns [`HURRAY_OK`] the bytes on the sink are not a container: the index
// a reader opens from is written here. Calling it twice *after it returned*
// [`HURRAY_OK`] fails.
//
// A footer that failed **before any of its bytes reached the sink** may be written again:
// nothing was emitted, so the file is still completable (ADR-041 § 6b). This is the one
// retry worth having here — the data is already on the sink, and only the index is
// missing. A footer that failed after its first byte poisons the writer like any other
// torn item.
//
// `kv` MAY be null with a `kv_count` of `0` for a file with no metadata section. Keys
// MUST be non-empty, at most 65 535 bytes, and unique. Entries read out of another file
// with [`hurray_file_reader_kv_entry`][crate::file::hurray_file_reader_kv_entry] can be
// passed straight in.
//
// The writer handle stays alive and MUST still be destroyed with
// [`hurray_file_writer_destroy`]; any flush or close belongs to the transport's release
// callback, because only the caller knows what its sink is.
//
// # Safety
//
// - `handle` MUST point to a live [`HurrayFileWriter`].
// - If `kv_count` is non-zero, `kv` MUST point to `kv_count` readable
//   [`HurrayKvEntry`] values whose own pointers are readable for their declared lengths,
//   all unmodified until this call returns.

HurrayStatus hurray_file_writer_finish(struct HurrayFileWriter *handle,
                                       const struct HurrayKvEntry *kv,
                                       uintptr_t kv_count)
;

// Creates a file writer over `transport` and writes the 64-byte file header.
//
// The header goes out here, not on the first tensor, which is what makes every later
// offset in the file knowable without seeking back.
//
// # Arguments
//
// - `transport` — Non-null; its `write` callback MUST be non-null. `read_at` and `size`
//   are not used: a file writer never reads what it has written.
// - `options` — MAY be null for [`HurrayFileWriterOptions`]' documented defaults.
// - `out_handle` — Non-null pointer to a `*mut HurrayFileWriter`; set on success.
//
// Returns [`HURRAY_ERR_INVALID_FILE`][crate::HURRAY_ERR_INVALID_FILE] if
// `data_buffer_alignment` is not a power of two in range.
//
// # Safety
//
// - `transport` MUST point to a readable [`HurrayTransport`] for the duration of the call.
// - `options`, if non-null, MUST point to a readable [`HurrayFileWriterOptions`].
// - `out_handle` MUST be a valid, non-null, writable pointer.

HurrayStatus hurray_file_writer_new(const struct HurrayTransport *transport,
                                    const struct HurrayFileWriterOptions *options,
                                    struct HurrayFileWriter **out_handle)
;

// Writes a composite: its head, then every member in order, each with its own name and
// its own footer-index entry.
//
// `nodes` is the composite in preorder: `nodes[0]` is the head, and each node declares
// how many of the nodes after it are its direct members. [`crate::composite`] has the
// shape and an example layout. Unlike the stream surface, **every node's name is
// required** — a reader recovers membership from the head's `member_count` and the file
// order of the entries after it, so each tensor needs an entry to be found by.
//
// The whole tree is validated and flattened into write order before a byte goes out, so
// an invalid composite never reaches the sink.
//
// Returns:
//
// - [`HURRAY_OK`] — the composite is entirely written and the payload pointers are no
//   longer held.
// - [`HURRAY_ERR_NOT_COMPOSITE`][crate::HURRAY_ERR_NOT_COMPOSITE] — `count` is `0`, or
//   `nodes[0]` is not a composite head. Use [`hurray_file_writer_write_tensor`] for a
//   tensor.
// - [`HURRAY_ERR_INDEX_OUT_OF_BOUNDS`][crate::HURRAY_ERR_INDEX_OUT_OF_BOUNDS] — the
//   member counts do not describe the array: a head declares members the array does not
//   carry, or nodes trail after the head's subtree is complete.
// - [`HURRAY_ERR_INVALID_FILE`][crate::HURRAY_ERR_INVALID_FILE] — a name is empty, too
//   long, or already used in this file. The head's name is checked before any byte goes
//   out, so the file is still completable; a **member's** name is checked when that
//   member is submitted, by which point the head is on the sink, so the writer is
//   poisoned — the group can no longer be completed and no index may be written over it.
//   Check names before calling if that distinction matters.
// - [`HURRAY_ERR_INVALID_LAYOUT`][crate::HURRAY_ERR_INVALID_LAYOUT] — the tree is not a
//   valid composite: a member count that disagrees with its head, a partition that does
//   not cover its index space, an overlay whose base is not first.
// - [`HURRAY_ERR_SINK_CLOSED`] — the sink stopped accepting bytes, or a write callback
//   failed, once part of the group was already out. The writer is poisoned: a head with
//   fewer members after it than it declares is not a file any reader may open, and a
//   forward-only writer cannot go back to fix it.
// - Whatever status the write callback returned, if it failed **before any byte of the
//   group reached the sink**. Nothing was emitted, so the call MAY be retried and the
//   file is still completable (ADR-041 § 6b).
//
// # Safety
//
// - `handle` MUST point to a live [`HurrayFileWriter`].
// - If `count` is non-zero, `nodes` MUST point to `count` readable
//   [`HurrayCompositeNode`] values, each satisfying that type's own pointer contract.
// - All of that memory MUST stay valid and unmodified until this call returns.

HurrayStatus hurray_file_writer_write_composite(struct HurrayFileWriter *handle,
                                                const struct HurrayCompositeNode *nodes,
                                                uintptr_t count)
;

// Writes one tensor under `name`: its descriptor, its padding, then its data buffers.
//
// `payloads` MUST have one entry per buffer in the descriptor's buffer table, in that
// order, each with the declared `byte_size`. The whole tensor is validated before a byte
// reaches the sink. The name is recorded in the footer index, so it is what
// [`hurray_file_reader_read_tensor`][crate::file::hurray_file_reader_read_tensor] will
// ask for; it MUST be non-empty, at most 65 535 bytes, and unique within the file.
//
// Returns:
//
// - [`HURRAY_OK`] — the tensor is entirely written and the payload pointers are no
//   longer held.
// - [`HURRAY_ERR_INVALID_FILE`][crate::HURRAY_ERR_INVALID_FILE] — the name is empty, too
//   long, or already used in this file. Refused before a byte goes out, so the file is
//   still completable and another name may be used.
// - [`HURRAY_ERR_SINK_CLOSED`] — the sink stopped accepting bytes, or the write callback
//   failed, once part of this tensor was already out. A torn tensor is in the file and a
//   forward-only writer cannot get back to its start, so the writer is poisoned: every
//   later call fails, including the footer, and the bytes on the sink are not a container.
// - Whatever status the write callback returned, if it failed **before any byte of this
//   tensor reached the sink**. Nothing was emitted, so the call MAY be retried — under the
//   same name, which the failed attempt did not consume — and the file is still
//   completable (ADR-041 § 6b).
//
// A composite is written with [`hurray_file_writer_write_composite`]; a composite head
// offered here is refused, because a head alone is not a valid tensor.
//
// # Safety
//
// - `handle` MUST point to a live [`HurrayFileWriter`] and `descriptor` to a live
//   [`HurrayDescriptor`].
// - `name` MUST be readable for `name_len` bytes.
// - If `count` is non-zero, `payloads` MUST point to `count` readable [`HurrayIoSlice`]
//   values, each describing memory readable for its own `len` bytes.
// - All of that memory MUST stay valid and unmodified until this call returns.

HurrayStatus hurray_file_writer_write_tensor(struct HurrayFileWriter *handle,
                                             const uint8_t *name,
                                             uintptr_t name_len,
                                             const struct HurrayDescriptor *descriptor,
                                             const struct HurrayIoSlice *payloads,
                                             uintptr_t count)
;

// Destroys an item, every tensor and name it owns, then writes null through `handle`.
//
// One call for a whole composite subtree: the nodes' `tensor` pointers were borrowed and
// are released here, so a caller that destroyed them individually would double-free.
//
// # Safety
//
// - `handle` MUST be a valid, non-null pointer to a `*mut HurrayItem` produced by
//   [`hurray_reader_next_item`][crate::hurray_reader_next_item] or
//   [`hurray_file_reader_read_composite`][crate::hurray_file_reader_read_composite].
// - That item MUST NOT have been destroyed already.
 HurrayStatus hurray_item_destroy(struct HurrayItem **handle) ;

// The item's own kind: [`HURRAY_ITEM_TENSOR`] or [`HURRAY_ITEM_COMPOSITE`].
//
// The kind of node `0`, which a caller that only wants to know whether a composite
// arrived can ask for without walking.
//
// # Safety
//
// `handle` and `out_kind` MUST be valid, non-null pointers.
 HurrayStatus hurray_item_kind(const struct HurrayItem *handle, uint8_t *out_kind) ;

// Copies node `index` into `out_node`.
//
// Nodes are in preorder: node `0` is the root, and a node's `member_count` direct members
// begin at the next index, each followed immediately by its own subtree. The pointers
// inside the node borrow from the item and are valid until [`hurray_item_destroy`].
//
// Returns [`HURRAY_ERR_INDEX_OUT_OF_BOUNDS`] if `index` is past the end.
//
// # Safety
//
// `handle` MUST point to a live [`HurrayItem`], and `out_node` MUST be a valid, non-null
// pointer writable for one [`HurrayItemNode`].

HurrayStatus hurray_item_node(const struct HurrayItem *handle,
                              uint64_t index,
                              struct HurrayItemNode *out_node)
;

// How many nodes the item has in total, counting the root and every nested member.
//
// `1` for a plain tensor.
//
// # Safety
//
// `handle` and `out_count` MUST be valid, non-null pointers.
 HurrayStatus hurray_item_node_count(const struct HurrayItem *handle, uint64_t *out_count) ;

// Destroys a reader, releases its transport context, and writes null through `handle`.
//
// Tensors already produced by [`hurray_reader_next_tensor`] are unaffected: each owns its
// own buffers and outlives the reader.
//
// # Safety
//
// - `handle` MUST be a valid, non-null pointer to a `*mut HurrayReader` from
//   [`hurray_reader_new`].
// - That reader MUST NOT have been destroyed already.
 HurrayStatus hurray_reader_destroy(struct HurrayReader **handle) ;

// Creates a reader over `transport`.
//
// The vtable is copied, so the caller MAY free the [`HurrayTransport`] struct immediately;
// its `ctx` must stay valid until the reader is destroyed, at which point the vtable's
// release callback is invoked.
//
// # Arguments
//
// - `transport` — Non-null; its `read` callback MUST be non-null.
// - `options` — MAY be null for [`HurrayReaderOptions`]' documented defaults.
// - `out_handle` — Non-null pointer to a `*mut HurrayReader`; set on success.
//
// # Safety
//
// - `transport` MUST point to a readable [`HurrayTransport`] for the duration of the call.
// - `options`, if non-null, MUST point to a readable [`HurrayReaderOptions`].
// - `out_handle` MUST be a valid, non-null, writable pointer.

HurrayStatus hurray_reader_new(const struct HurrayTransport *transport,
                               const struct HurrayReaderOptions *options,
                               struct HurrayReader **out_handle)
;

// Reads the next *item*: one tensor, or a composite and everything under it.
//
// The assembled view of the same bytes [`hurray_reader_next_tensor`] reads flat. A
// composite head and its members arrive as one [`HurrayItem`] whose nodes a caller walks
// in preorder — see [`crate::item`] for the shape, and `hurray_item_node` for the walk.
//
// Returns:
//
// - [`HURRAY_OK`] — `*out_item` is a new [`HurrayItem`], to be released with
//   [`hurray_item_destroy`][crate::hurray_item_destroy].
// - [`HURRAY_END_OF_STREAM`] — input ended cleanly at an item boundary. `*out_item` is
//   untouched.
// - [`HURRAY_ERR_INVALID_STREAM`][crate::HURRAY_ERR_INVALID_STREAM] — the stream ended
//   with a composite head still owed members, or a group failed validation (member
//   count, partition coverage, overlay ordering).
// - [`HURRAY_ERR_LIMIT_EXCEEDED`][crate::HURRAY_ERR_LIMIT_EXCEEDED] — nesting exceeded
//   `max_composite_depth`.
// - Whatever status the read callback returned, if it failed. The reader's position is
//   intact, so the same call MAY be retried and resumes mid-tensor.
//
// Both views come from one core, and the assembly happens on this side of it. So mixing
// the two calls on one reader is allowed but rarely meant: a
// [`hurray_reader_next_tensor`] issued while a composite head is open takes the member
// that head was waiting for, and the group stays open for the rest of the stream.
//
// # Safety
//
// - `handle` MUST point to a live [`HurrayReader`].
// - `out_item` MUST be a valid, non-null, writable pointer.
 HurrayStatus hurray_reader_next_item(struct HurrayReader *handle, struct HurrayItem **out_item) ;

// Reads the next tensor, blocking in the transport's read callback as needed.
//
// Returns:
//
// - [`HURRAY_OK`] — `*out_tensor` is a new [`HurrayTensor`], to be released with
//   [`hurray_tensor_destroy`][crate::hurray_tensor_destroy].
// - [`HURRAY_END_OF_STREAM`] — input ended cleanly at a tensor boundary. `*out_tensor` is
//   untouched. Positive, because this is how a stream ends, not a failure.
// - [`HURRAY_ERR_UNEXPECTED_EOF`][crate::HURRAY_ERR_UNEXPECTED_EOF] — input ended inside
//   a descriptor or a buffer.
// - Whatever status the read callback returned, if it failed. The reader's position is
//   intact in that case — the transport contract says a failing callback moved no bytes —
//   so **the same call MAY be retried** and will resume mid-tensor rather than restart it.
//
// A composite head arrives as the buffer-less tensor it is on the wire, and its members
// as the tensors that follow it. Use [`hurray_reader_next_item`] to have them assembled
// into one walkable item instead.
//
// Every buffer in the returned tensor points at memory the read core allocated at the
// alignment its buffer handle *declares*, and the transport wrote into it directly — so a
// SIMD load on it is sound, and no copy of the payload happened after that write.
//
// # Safety
//
// - `handle` MUST point to a live [`HurrayReader`].
// - `out_tensor` MUST be a valid, non-null, writable pointer.

HurrayStatus hurray_reader_next_tensor(struct HurrayReader *handle,
                                       struct HurrayTensor **out_tensor)
;

// Reads the ABI version recorded by the producing build.
//
// **Call this first.** It is the one accessor guaranteed to work on a tensor produced by
// any version of this ABI, and every other accessor assumes a caller that has already
// compared this value against its own
// [`HURRAY_C_ABI_VERSION`](crate::HURRAY_C_ABI_VERSION) and found it equal (ADR-043
// § 5). That ordering is what lets later versions add accessors without breaking
// consumers compiled against an earlier header.
//
// A tensor from a stream or file read reports this library's version; one from
// [`hurray_tensor_new`] reports what its producer passed.
//
// # Safety
//
// `handle` and `out` MUST be valid, non-null pointers.
//
// # Examples
//
// ```
// # use hurray_core::{
// #     BufferHandle, DeviceTag, ElementType, LayoutDescriptor, Shape, SyncMode,
// #     TensorDescriptor, MIN_BUFFER_ALIGNMENT,
// # };
// use hurray_ffi::tensor::{
//     hurray_tensor_abi_version, hurray_tensor_destroy, hurray_tensor_new,
// };
// use hurray_ffi::{
//     hurray_buffer_list_new, HurrayBufferList, HurrayTensor, HURRAY_C_ABI_VERSION, HURRAY_OK,
// };
// # let handle = BufferHandle::new(16, MIN_BUFFER_ALIGNMENT, DeviceTag::Cpu, SyncMode::ProducerSynced)?;
// # let descriptor = TensorDescriptor::new(
// #     1, 0, ElementType::Float32, Shape::new(vec![4])?, 0, LayoutDescriptor::RowMajor,
// #     vec![handle], None, None, None, None,
// # )?;
// # let encoded = descriptor.encode()?;
// # let mut buffers: *mut HurrayBufferList = std::ptr::null_mut();
// # unsafe { hurray_buffer_list_new(1, &mut buffers) };
// # let mut tensor: *mut HurrayTensor = std::ptr::null_mut();
// # unsafe {
// #     hurray_tensor_new(
// #         HURRAY_C_ABI_VERSION, encoded.as_ptr(), encoded.len() as u64, buffers,
// #         std::ptr::null_mut(), None, &mut tensor,
// #     )
// # };
// let mut version: u32 = 0;
// assert_eq!(
//     unsafe { hurray_tensor_abi_version(tensor, &mut version) },
//     HURRAY_OK,
// );
// if version != HURRAY_C_ABI_VERSION {
//     // Producer and consumer disagree — refuse rather than dereference further.
//     return Ok(());
// }
// # unsafe { hurray_tensor_destroy(&mut tensor) };
// # Ok::<(), Box<dyn std::error::Error>>(())
// ```

HurrayStatus hurray_tensor_abi_version(const struct HurrayTensor *handle,
                                       uint32_t *out)
;

// Borrows the tensor's buffer list.
//
// Element `i` of the list is buffer `i` of the descriptor's buffer table. The list is
// **borrowed**: the caller MUST NOT call [`hurray_buffer_list_destroy`] on it, and MUST
// keep the tensor alive while it reads the buffers.
//
// # Safety
//
// `handle` and `out_buffers` MUST be valid, non-null pointers.
//
// # Examples
//
// ```
// # use hurray_core::{
// #     BufferHandle, DeviceTag, ElementType, LayoutDescriptor, Shape, SyncMode,
// #     TensorDescriptor, MIN_BUFFER_ALIGNMENT,
// # };
// use hurray_ffi::buffer_list::hurray_buffer_list_len;
// use hurray_ffi::tensor::{hurray_tensor_buffers, hurray_tensor_destroy, hurray_tensor_new};
// use hurray_ffi::{
//     hurray_buffer_list_new, HurrayBufferList, HurrayTensor, HURRAY_C_ABI_VERSION, HURRAY_OK,
// };
// # let handle = BufferHandle::new(16, MIN_BUFFER_ALIGNMENT, DeviceTag::Cpu, SyncMode::ProducerSynced)?;
// # let descriptor = TensorDescriptor::new(
// #     1, 0, ElementType::Float32, Shape::new(vec![4])?, 0, LayoutDescriptor::RowMajor,
// #     vec![handle], None, None, None, None,
// # )?;
// # let encoded = descriptor.encode()?;
// # let mut buffers: *mut HurrayBufferList = std::ptr::null_mut();
// # unsafe { hurray_buffer_list_new(1, &mut buffers) };
// # let mut tensor: *mut HurrayTensor = std::ptr::null_mut();
// # unsafe {
// #     hurray_tensor_new(
// #         HURRAY_C_ABI_VERSION, encoded.as_ptr(), encoded.len() as u64, buffers,
// #         std::ptr::null_mut(), None, &mut tensor,
// #     )
// # };
// let mut borrowed: *mut HurrayBufferList = std::ptr::null_mut();
// assert_eq!(
//     unsafe { hurray_tensor_buffers(tensor, &mut borrowed) },
//     HURRAY_OK,
// );
//
// let mut len: u64 = 0;
// unsafe { hurray_buffer_list_len(borrowed, &mut len) };
// # unsafe { hurray_tensor_destroy(&mut tensor) };
// # Ok::<(), Box<dyn std::error::Error>>(())
// ```

HurrayStatus hurray_tensor_buffers(const struct HurrayTensor *handle,
                                   struct HurrayBufferList **out_buffers)
;

// Borrows the tensor's descriptor handle.
//
// The returned handle carries every accessor in [`crate::descriptor`] and
// [`crate::field`]. It is **borrowed**: the caller MUST NOT call
// [`hurray_descriptor_destroy`] on it, and MUST keep the tensor alive while it reads.
//
// # Safety
//
// `handle` and `out_descriptor` MUST be valid, non-null pointers.
//
// # Examples
//
// ```
// # use hurray_core::{
// #     BufferHandle, DeviceTag, ElementType, LayoutDescriptor, Shape, SyncMode,
// #     TensorDescriptor, MIN_BUFFER_ALIGNMENT,
// # };
// use hurray_ffi::descriptor::hurray_descriptor_rank;
// use hurray_ffi::tensor::{hurray_tensor_descriptor, hurray_tensor_destroy, hurray_tensor_new};
// use hurray_ffi::{
//     hurray_buffer_list_new, HurrayBufferList, HurrayDescriptor, HurrayTensor,
//     HURRAY_C_ABI_VERSION, HURRAY_OK,
// };
// # let handle = BufferHandle::new(16, MIN_BUFFER_ALIGNMENT, DeviceTag::Cpu, SyncMode::ProducerSynced)?;
// # let descriptor = TensorDescriptor::new(
// #     1, 0, ElementType::Float32, Shape::new(vec![4])?, 0, LayoutDescriptor::RowMajor,
// #     vec![handle], None, None, None, None,
// # )?;
// # let encoded = descriptor.encode()?;
// # let mut buffers: *mut HurrayBufferList = std::ptr::null_mut();
// # unsafe { hurray_buffer_list_new(1, &mut buffers) };
// # let mut tensor: *mut HurrayTensor = std::ptr::null_mut();
// # unsafe {
// #     hurray_tensor_new(
// #         HURRAY_C_ABI_VERSION, encoded.as_ptr(), encoded.len() as u64, buffers,
// #         std::ptr::null_mut(), None, &mut tensor,
// #     )
// # };
// let mut descriptor: *mut HurrayDescriptor = std::ptr::null_mut();
// assert_eq!(
//     unsafe { hurray_tensor_descriptor(tensor, &mut descriptor) },
//     HURRAY_OK,
// );
//
// let mut rank: u32 = 0;
// unsafe { hurray_descriptor_rank(descriptor, &mut rank) };
// assert_eq!(rank, 1);
// # unsafe { hurray_tensor_destroy(&mut tensor) };
// # Ok::<(), Box<dyn std::error::Error>>(())
// ```

HurrayStatus hurray_tensor_descriptor(const struct HurrayTensor *handle,
                                      struct HurrayDescriptor **out_descriptor)
;

// Destroys a tensor handle — its descriptor, every buffer it owns, and its owner
// reference — then writes null through `handle`.
//
// One call rather than two, so the teardown order is not the caller's problem. A
// non-null `owner_release` is invoked exactly once, with the `owner` pointer given at
// construction.
//
// # Safety
//
// - `handle` MUST be a valid, non-null pointer to a `*mut HurrayTensor` produced by
//   [`hurray_tensor_new`], by [`hurray_reader_next_tensor`][crate::hurray_reader_next_tensor],
//   by [`hurray_file_reader_read_tensor`][crate::hurray_file_reader_read_tensor], or
//   taken out of a native-protocol capsule.
// - That tensor MUST NOT have been destroyed already.
//
// # Examples
//
// ```
// # use hurray_core::{
// #     BufferHandle, DeviceTag, ElementType, LayoutDescriptor, Shape, SyncMode,
// #     TensorDescriptor, MIN_BUFFER_ALIGNMENT,
// # };
// use hurray_ffi::tensor::{hurray_tensor_destroy, hurray_tensor_new};
// use hurray_ffi::{
//     hurray_buffer_list_new, HurrayBufferList, HurrayTensor, HURRAY_C_ABI_VERSION,
//     HURRAY_ERR_INTERNAL, HURRAY_OK,
// };
// # let handle = BufferHandle::new(16, MIN_BUFFER_ALIGNMENT, DeviceTag::Cpu, SyncMode::ProducerSynced)?;
// # let descriptor = TensorDescriptor::new(
// #     1, 0, ElementType::Float32, Shape::new(vec![4])?, 0, LayoutDescriptor::RowMajor,
// #     vec![handle], None, None, None, None,
// # )?;
// # let encoded = descriptor.encode()?;
// # let mut buffers: *mut HurrayBufferList = std::ptr::null_mut();
// # unsafe { hurray_buffer_list_new(1, &mut buffers) };
// # let mut tensor: *mut HurrayTensor = std::ptr::null_mut();
// # unsafe {
// #     hurray_tensor_new(
// #         HURRAY_C_ABI_VERSION, encoded.as_ptr(), encoded.len() as u64, buffers,
// #         std::ptr::null_mut(), None, &mut tensor,
// #     )
// # };
// assert_eq!(unsafe { hurray_tensor_destroy(&mut tensor) }, HURRAY_OK);
// assert!(tensor.is_null());
//
// // A second destroy finds the caller's variable dead and says so, rather than
// // freeing anything twice.
// assert_eq!(
//     unsafe { hurray_tensor_destroy(&mut tensor) },
//     HURRAY_ERR_INTERNAL,
// );
// # Ok::<(), Box<dyn std::error::Error>>(())
// ```

HurrayStatus hurray_tensor_destroy(struct HurrayTensor **handle)
;

// Creates a [`HurrayTensor`] from an encoded descriptor and a finished buffer list.
//
// `abi_version` MUST be the producing build's
// [`HURRAY_C_ABI_VERSION`](crate::HURRAY_C_ABI_VERSION); a consumer compares it against
// its own before trusting anything else about the handle.
//
// `descriptor_bytes` is **decoded during this call** and only the decoded form is kept,
// so a producer cannot export a tensor whose descriptor does not parse: bytes that fail
// to decode are rejected with the status the decode failed with. A null pointer or a
// `descriptor_len` of `0` is rejected with
// [`HURRAY_ERR_NULL_POINTER`](crate::HURRAY_ERR_NULL_POINTER) — a tensor with no
// descriptor is a carrier for bytes nothing can interpret.
//
// On success `buffers` is **owned by the tensor**, and the caller MUST NOT push into it,
// destroy it, or use the handle at all. On failure ownership stays with the caller, who
// MUST destroy it — the discipline
// [`hurray_buffer_list_push`](crate::buffer_list::hurray_buffer_list_push) already
// follows.
//
// `owner` and `owner_release` are optional and opaque. When `owner_release` is non-null
// it is invoked exactly once, with `owner`, during [`hurray_tensor_destroy`].
//
// # Safety
//
// - `out_tensor` MUST be a valid, non-null, writable pointer.
// - `descriptor_bytes` MUST point to at least `descriptor_len` readable bytes.
// - `buffers` MUST be a live list from
//   [`hurray_buffer_list_new`](crate::hurray_buffer_list_new) that nothing else owns.
// - `owner` MUST remain valid until `owner_release` is invoked.
//
// # Examples
//
// ```
// use hurray_core::{
//     BufferHandle, DeviceTag, ElementType, LayoutDescriptor, Shape, SyncMode,
//     TensorDescriptor, MIN_BUFFER_ALIGNMENT,
// };
// use hurray_ffi::tensor::{hurray_tensor_destroy, hurray_tensor_new};
// use hurray_ffi::{
//     hurray_buffer_list_new, HurrayBufferList, HurrayTensor, HURRAY_C_ABI_VERSION, HURRAY_OK,
// };
//
// let handle = BufferHandle::new(
//     16,
//     MIN_BUFFER_ALIGNMENT,
//     DeviceTag::Cpu,
//     SyncMode::ProducerSynced,
// )?;
// let descriptor = TensorDescriptor::new(
//     1,
//     0,
//     ElementType::Float32,
//     Shape::new(vec![4])?,
//     0,
//     LayoutDescriptor::RowMajor,
//     vec![handle],
//     None,
//     None,
//     None,
//     None,
// )?;
// let encoded = descriptor.encode()?;
//
// // An empty list is enough to show the ownership transfer; a real producer pushes
// // one buffer per descriptor buffer-table entry first.
// let mut buffers: *mut HurrayBufferList = std::ptr::null_mut();
// assert_eq!(unsafe { hurray_buffer_list_new(1, &mut buffers) }, HURRAY_OK);
//
// let mut tensor: *mut HurrayTensor = std::ptr::null_mut();
// assert_eq!(
//     unsafe {
//         hurray_tensor_new(
//             HURRAY_C_ABI_VERSION,
//             encoded.as_ptr(),
//             encoded.len() as u64,
//             buffers, // ownership transfers on success
//             std::ptr::null_mut(),
//             None,
//             &mut tensor,
//         )
//     },
//     HURRAY_OK,
// );
//
// // One call ends the whole tensor: descriptor, buffers, and the owner reference.
// assert_eq!(unsafe { hurray_tensor_destroy(&mut tensor) }, HURRAY_OK);
// assert!(tensor.is_null()); // destroy nulls the caller's pointer
// # Ok::<(), Box<dyn std::error::Error>>(())
// ```

HurrayStatus hurray_tensor_new(uint32_t abi_version,
                               const uint8_t *descriptor_bytes,
                               uint64_t descriptor_len,
                               struct HurrayBufferList *buffers,
                               void *owner,
                               HurrayOwnerReleaseFn owner_release,
                               struct HurrayTensor **out_tensor)
;

// Destroys a writer, releases its transport context, and writes null through `handle`.
//
// There is nothing to flush: a tensor is fully on the wire, or the call that wrote it
// failed. The transport's own close, if it has one, belongs in its release callback.
//
// # Safety
//
// - `handle` MUST be a valid, non-null pointer to a `*mut HurrayWriter` from
//   [`hurray_writer_new`].
// - That writer MUST NOT have been destroyed already.
 HurrayStatus hurray_writer_destroy(struct HurrayWriter **handle) ;

// Creates a writer over `transport`.
//
// The vtable is copied, so the caller MAY free the [`HurrayTransport`] struct immediately;
// its `ctx` must stay valid until the writer is destroyed, at which point the vtable's
// release callback is invoked.
//
// # Arguments
//
// - `transport` — Non-null; its `write` callback MUST be non-null.
// - `options` — MAY be null for [`HurrayWriterOptions`]' documented defaults.
// - `out_handle` — Non-null pointer to a `*mut HurrayWriter`; set on success.
//
// # Safety
//
// - `transport` MUST point to a readable [`HurrayTransport`] for the duration of the call.
// - `options`, if non-null, MUST point to a readable [`HurrayWriterOptions`].
// - `out_handle` MUST be a valid, non-null, writable pointer.

HurrayStatus hurray_writer_new(const struct HurrayTransport *transport,
                               const struct HurrayWriterOptions *options,
                               struct HurrayWriter **out_handle)
;

// Writes a composite — its head, then every member, nested ones included — as one item.
//
// `nodes` is the composite in preorder: `nodes[0]` is the head, and each node declares
// how many of the nodes after it are its direct members. [`crate::composite`] has the
// shape and an example layout; names are ignored here, because the stream wire carries
// none.
//
// The whole tree is validated before a byte reaches the sink — member counts at every
// level, partition exact-cover, overlay base-first ordering — so an invalid composite is
// refused rather than half written. Payload slices stay borrowed throughout: nothing is
// copied or concatenated (ADR-041 § 3).
//
// Returns:
//
// - [`HURRAY_OK`] — the composite is entirely written and the payload pointers are no
//   longer held.
// - [`HURRAY_ERR_NOT_COMPOSITE`][crate::HURRAY_ERR_NOT_COMPOSITE] — `count` is `0`, or
//   `nodes[0]` is not a composite head.
//   Use [`hurray_writer_write_tensor`] for a tensor.
// - [`HURRAY_ERR_INDEX_OUT_OF_BOUNDS`][crate::HURRAY_ERR_INDEX_OUT_OF_BOUNDS] — the
//   member counts do not describe the array: a head declares members the array does not
//   carry, or nodes trail after the head's subtree is complete.
// - [`HURRAY_ERR_INVALID_LAYOUT`][crate::HURRAY_ERR_INVALID_LAYOUT] — the tree is not a
//   valid composite: a head that is not one, a member count that disagrees with the
//   head, a partition that does not cover its index space, an overlay whose base is not
//   first. Refused before a byte moved, so the writer stays usable.
// - [`HURRAY_ERR_SINK_CLOSED`] — the sink stopped accepting bytes mid-composite, so a
//   truncated item is on the wire and the writer is poisoned. A composite is one item:
//   there is no partially valid composite to resume from.
// - Whatever status the write callback returned, if it failed **before any byte of this
//   composite reached the sink**. Nothing was emitted, so the call MAY be retried.
//
// # Safety
//
// - `handle` MUST point to a live [`HurrayWriter`].
// - If `count` is non-zero, `nodes` MUST point to `count` readable
//   [`HurrayCompositeNode`] values, each satisfying that type's own pointer contract.
// - All of that memory MUST stay valid and unmodified until this call returns.

HurrayStatus hurray_writer_write_composite(struct HurrayWriter *handle,
                                           const struct HurrayCompositeNode *nodes,
                                           uintptr_t count)
;

// Writes one tensor — its descriptor then its payloads — blocking in the transport's
// write callback as needed.
//
// `payloads` MUST have one entry per buffer in the descriptor's buffer table, in that
// order, each with the declared `byte_size`. The whole tensor is validated before a byte
// reaches the sink, so a mismatch is reported without putting a torn item on the wire.
//
// Returns:
//
// - [`HURRAY_OK`] — the tensor is entirely written and the payload pointers are no longer
//   held.
// - [`HURRAY_ERR_SINK_CLOSED`] — the sink stopped accepting bytes mid-tensor, so a
//   truncated item is on the wire. The writer is poisoned: every later call fails, and a
//   fresh writer over the same connection is not a recovery.
// - Whatever status the write callback returned, if it failed **before any byte of this
//   tensor reached the sink**. Nothing was emitted, so the call MAY be retried. A failure
//   after the first byte is reported as [`HURRAY_ERR_SINK_CLOSED`] instead, because at
//   that point the damage is the same.
//
// A composite is written with [`hurray_writer_write_composite`]; a composite head offered
// here is refused, because a head alone is not a valid tensor.
//
// # Safety
//
// - `handle` MUST point to a live [`HurrayWriter`] and `descriptor` to a live
//   [`HurrayDescriptor`].
// - If `count` is non-zero, `payloads` MUST point to `count` readable [`HurrayIoSlice`]
//   values, each describing memory readable for its own `len` bytes.
// - All of that memory MUST stay valid and unmodified until this call returns.

HurrayStatus hurray_writer_write_tensor(struct HurrayWriter *handle,
                                        const struct HurrayDescriptor *descriptor,
                                        const struct HurrayIoSlice *payloads,
                                        uintptr_t count)
;

#endif  /* HURRAY_H */
